"""Luhn algorithm validation for card numbers."""


def valid(number):
    """Return True if *number* is valid according to the Luhn algorithm.

    Spaces are ignored. After removing spaces, the value must contain at
    least two characters and consist only of ASCII digits 0-9.
    """
    if not isinstance(number, str):
        return False

    digits = number.replace(" ", "")

    if len(digits) < 2:
        return False
    if any(ch < "0" or ch > "9" for ch in digits):
        return False

    total = 0
    parity = len(digits) % 2

    for index, ch in enumerate(digits):
        value = ord(ch) - ord("0")
        if index % 2 == parity:
            value *= 2
            if value > 9:
                value -= 9
        total += value

    return total % 10 == 0
